mapper.select:
select 

from PTL_GOAL
where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
  and ASSET_CLASSIFY = #{assetClassify,jdbcType=VARCHAR}

mapper.delete:
delete from PTL_GOAL
where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
  and ASSET_CLASSIFY = #{assetClassify,jdbcType=VARCHAR}

mapper.update:
update PTL_GOAL
set INVEST_MAX = #{investMax,jdbcType=DECIMAL},
    INVEST_MIN = #{investMin,jdbcType=DECIMAL},
    REMARK = #{remark,jdbcType=VARCHAR},
    UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
    UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
  and ASSET_CLASSIFY = #{assetClassify,jdbcType=VARCHAR}
